from openai import OpenAI

client = OpenAI()

META = ("Rewrite the following prompt to be clearer, more specific, and produce better answers. "
        "Only output the new prompt.")

def optimize(prompt: str) -> str:
    r = client.chat.completions.create(
        model="{{model_name}}",
        messages=[{"role": "system", "content": META},
                  {"role": "user", "content": prompt}],
    )
    return r.choices[0].message.content.strip()

if __name__ == "__main__":
    print(optimize("tell me about cats"))
